    #[test]
    fn a_written_recipe_names_files_that_land_where_wan2gp_looks_for_them() {
        // Wan2GP saves a downloaded URL under its basename next to the other
        // checkpoints. If the recipe's file name could not be a legal file name,
        // the download would land somewhere the loader never looks.
        let td = crate::base::TestDataDir::new();
        td.seed_wgp_config("{}");
        let ft = arr(manifest(), "finetunes")[0].clone();
        adult_pack_write_finetunes(vec![str_field(&ft, "id")]).expect("write");
        let urls: Vec<String> = arr(&ft, "urls")
            .iter()
            .filter_map(|u| u.as_str().map(String::from))
            .collect();
        for u in &urls {
            let name = basename(u);
            assert!(
                safe_file_name(&name).is_some(),
                "{name} would be rejected as a local file name"
            );
            assert!(
                !name.contains('?') && !name.contains('#'),
                "{name} carries URL syntax into the file name"
            );
        }
        // A HIGH/LOW recipe keeps its halves addressable, not merged.
        if !str_field(&ft, "fileLow").is_empty() {
            assert_eq!(
                arr(&ft, "urls2").len(),
                1,
                "the low half must have its own URL"
            );
            assert!(
                ft.get("sha256Low")
                    .and_then(|s| s.as_str())
                    .map(|s| !s.is_empty())
                    .unwrap_or(false),
                "the low half must be hash-verified on its own"
            );
        }
    }

    #[test]
    #[ignore = "network: downloads a real LoRA. Run with --ignored."]
    fn a_real_lora_downloads_verifies_and_resumes() {
        // The one test that touches the internet, and the one that matters most:
        // a catalog file must actually arrive, match its pinned SHA-256, be
        // reused rather than re-fetched, and resume from a partial file. The
        // smallest catalog entry is used so this stays a few MB.
        // Mutex, not RefCell: the sink is Send + Sync because the download future
        // is held across an await inside a Tauri command.
        #[derive(Default)]
        struct Collect(std::sync::Mutex<Vec<Value>>);
        impl ProgressSink for Collect {
            fn emit(&self, p: Value) {
                self.0.lock().unwrap().push(p);
            }
        }
        impl Collect {
            fn events(&self) -> Vec<Value> {
                self.0.lock().unwrap().clone()
            }
        }

        let td = crate::base::TestDataDir::new();
        td.seed_wgp_config("{}");
        let item = arr(manifest(), "loras")
            .iter()
            .min_by_key(|l| l.get("bytes").and_then(|b| b.as_u64()).unwrap_or(u64::MAX))
            .cloned()
            .expect("catalog has loras");
        let url = str_field(&item, "url");
        let sha = str_field(&item, "sha256");
        let bytes = item.get("bytes").and_then(|b| b.as_u64()).unwrap_or(0);
        assert_eq!(sha.len(), 64, "the pin must be a sha256");
        assert!(url.starts_with("https://"), "catalog urls must be https");

        let dest = std::env::temp_dir().join(format!("adult-pack-net-test-{}", &sha[..12]));
        let _ = std::fs::remove_file(&dest);
        let rt = tokio::runtime::Runtime::new().expect("runtime");
        let sink = Collect::default();

        // 1. Cold download lands the exact pinned bytes.
        let n = rt.block_on(async {
            download_verified(
                &http_client(),
                &url,
                &dest,
                Some(&sha),
                bytes,
                &sink,
                "net",
                "net-test",
            )
            .await
            .expect("download")
        });
        assert_eq!(n, bytes, "downloaded size must equal the pinned size");
        assert_eq!(
            sha256_file(&dest).as_deref(),
            Some(sha.as_str()),
            "the file on disk must hash to the pinned value"
        );
        let phases: Vec<String> = sink
            .events()
            .iter()
            .filter_map(|e| e.get("phase").and_then(|p| p.as_str()).map(String::from))
            .collect();
        assert!(phases.contains(&"download".to_string()));
        assert!(phases.contains(&"verify".to_string()));
        assert!(phases.contains(&"done".to_string()));

        // 2. A second call is served from disk, not the network.
        let before = sink.events().len();
        let again = rt.block_on(async {
            download_verified(
                &http_client(),
                &url,
                &dest,
                Some(&sha),
                bytes,
                &sink,
                "net",
                "net-test",
            )
            .await
            .expect("cached")
        });
        assert_eq!(again, bytes);
        assert!(
            sink.events()[before..]
                .iter()
                .any(|e| e.get("cached").and_then(|c| c.as_bool()) == Some(true)),
            "an already-correct file must be reported as cached"
        );

        // 3. A truncated .part is resumed, not restarted.
        let part = part_path(&dest);
        let keep = (bytes / 3) as usize;
        std::fs::write(&part, &std::fs::read(&dest).unwrap()[..keep]).unwrap();
        std::fs::remove_file(&dest).unwrap();
        let keep_bytes = keep as u64;
        let before = sink.events().len();
        let resumed = rt.block_on(async {
            download_verified(
                &http_client(),
                &url,
                &dest,
                Some(&sha),
                bytes,
                &sink,
                "net",
                "net-test",
            )
            .await
            .expect("resume")
        });
        assert_eq!(resumed, bytes);
        assert_eq!(sha256_file(&dest).as_deref(), Some(sha.as_str()));
        // Proof it resumed rather than re-downloaded: the very first progress
        // event of a resumed transfer already reports bytes on hand.
        let first = sink.events()[before..]
            .iter()
            .find(|e| e.get("phase").and_then(|p| p.as_str()) == Some("download"))
            .cloned();
        let opened_at = first
            .as_ref()
            .and_then(|e| e.get("received").and_then(|r| r.as_u64()))
            .unwrap_or(0);
        assert!(
            opened_at >= keep_bytes,
            "resume started from {opened_at} bytes, expected at least {keep_bytes}"
        );

        // 4. A wrong hash is refused and leaves nothing behind.
        std::fs::remove_file(&dest).unwrap();
        let bad = "0".repeat(64);
        let err = rt.block_on(async {
            download_verified(
                &http_client(),
                &url,
                &dest,
                Some(&bad),
                bytes,
                &sink,
                "net",
                "net-test",
            )
            .await
        });
        assert!(err.is_err(), "a hash mismatch must fail the download");
        assert!(
            !dest.exists(),
            "a corrupt file must never be left where Wan2GP would load it"
        );
        assert!(
            !part.exists(),
            "the rejected .part must be discarded, not left to resume later"
        );
        // Clean up both names: leaving the .part behind would leak a full model
        // copy into the temp folder on every run.
        let _ = std::fs::remove_file(&dest);
        let _ = std::fs::remove_file(part_path(&dest));
    }

    #[test]
    #[ignore = "network: HEADs every recipe URL. Run with --ignored."]
    fn every_written_recipe_serves_the_bytes_it_promises() {
        // The promise this pack makes is "write the JSON and Wan2GP downloads
        // the model". That only holds if each URL in each recipe still resolves
        // to a file of the pinned size. HEADing all of them is the honest check:
        // downloading tens of gigabytes of checkpoints is not.
        let td = crate::base::TestDataDir::new();
        td.seed_wgp_config("{}");
        let rt = tokio::runtime::Runtime::new().expect("runtime");
        // The client must be built inside the runtime: reqwest needs a reactor
        // to exist before its pool does.
        let client = rt.block_on(async { http_client() });

        let ids: Vec<String> = arr(manifest(), "finetunes")
            .iter()
            .map(|f| str_field(f, "id"))
            .collect();
        adult_pack_write_finetunes(ids.clone()).expect("write all recipes");

        let mut checked = 0usize;
        let mut bad: Vec<String> = vec![];
        for id in &ids {
            let path = finetune_path(id).expect("recipe written");
            let doc: Value =
                serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
            let model = &doc["model"];
            let urls: Vec<String> = arr(model, "URLs")
                .iter()
                .chain(arr(model, "URLs2").iter())
                .filter_map(|u| u.as_str().map(String::from))
                .collect();
            assert!(
                !urls.is_empty(),
                "{id}: a recipe with no URL downloads nothing"
            );

            // The size the manifest pins for this exact file (HIGH, or LOW).
            let ft = find(manifest(), "finetunes", id)
                .cloned()
                .unwrap_or(json!({}));
            let pinned_by_url: Vec<(String, u64)> = arr(&ft, "urls")
                .iter()
                .filter_map(|u| u.as_str())
                .map(|u| {
                    (
                        u.to_string(),
                        ft.get("bytes").and_then(|b| b.as_u64()).unwrap_or(0),
                    )
                })
                .chain(
                    arr(&ft, "urls2")
                        .iter()
                        .filter_map(|u| u.as_str())
                        .map(|u| {
                            (
                                u.to_string(),
                                ft.get("bytesLow").and_then(|b| b.as_u64()).unwrap_or(0),
                            )
                        }),
                )
                .collect();

            for u in urls {
                let want = pinned_by_url
                    .iter()
                    .find(|(x, _)| *x == u)
                    .map(|(_, s)| *s)
                    .unwrap_or(0);
                // Build and poll the request inside the runtime: constructing reqwest's
                // future outside it panics with "no reactor running".
                let head = rt.block_on(async { client.head(&u).send().await });
                match head {
                    Ok(r) if r.status().is_success() => {
                        let len = r.content_length().unwrap_or(0);
                        if want > 0 && len > 0 && len != want {
                            bad.push(format!("{u}: serves {len} bytes, pinned {want}"));
                        }
                        checked += 1;
                    }
                    Ok(r) => bad.push(format!("{u}: HTTP {}", r.status())),
                    Err(e) => bad.push(format!("{u}: {e}")),
                }
            }
        }
        assert!(
            bad.is_empty(),
            "{} of {} recipe URL(s) no longer serve their pinned bytes:\n  {}",
            bad.len(),
            checked,
            bad.join("\n  ")
        );
        assert!(checked >= ids.len(), "every recipe must have been checked");
    }

    #[test]
    fn high_low_pairs_stay_together() {
        for l in arr(manifest(), "loras") {
            if l.get("defaultSelected").and_then(|v| v.as_bool()) != Some(true) {
                continue;
            }
            let src = str_field(l, "sourceId");
            let pair = str_field(l, "pair");
            if pair.is_empty() {
                continue;
            }
            let other = arr(manifest(), "loras").iter().any(|o| {
                str_field(o, "sourceId") == src
                    && str_field(o, "pair") != pair
                    && !str_field(o, "pair").is_empty()
            });
            let partner_selected = arr(manifest(), "loras").iter().any(|o| {
                str_field(o, "sourceId") == src
                    && str_field(o, "pair") != pair
                    && !str_field(o, "pair").is_empty()
                    && o.get("defaultSelected").and_then(|v| v.as_bool()) == Some(true)
            });
            if other {
                assert!(
                    partner_selected,
                    "{src}: selected {pair} without its partner half"
                );
            }
        }
    }

