    #[test]
    fn gallery_picks_images_and_videos() {
        // A video model's examples are .mp4 — an image-only picker would show
        // nothing at all for every Wan/H3/LTX repo.
        let files = vec![
            json!({"type":"file","path":"README.md","size":100}),
            json!({"type":"file","path":"preview.png","size":50_000}),
            json!({"type":"file","path":"images/big.png","size":40_000_000}),
            json!({"type":"file","path":"TEST__00035-audio.mp4","size":9_000_000}),
            json!({"type":"file","path":"TEST__00036-audio.mp4","size":7_000_000}),
            json!({"type":"file","path":"images/undefined_image (1).png","size":1000}),
            json!({"type":"file","path":"huge.mp4","size":900_000_000}),
            json!({"type":"file","path":".gitattributes","size":10}),
        ];
        let (images, videos) = media_files(&files);
        assert_eq!(images, vec!["preview.png"], "oversized/junk images dropped");
        // Largest first: the polished sample clip is usually the biggest.
        assert_eq!(
            videos,
            vec!["TEST__00035-audio.mp4", "TEST__00036-audio.mp4"]
        );
    }

